import itertools
import random
import math

n = 21

def count_conflicts_fast(colors, n):
    """Count number of monochromatic cliques - optimized"""
    conflicts = 0
    # Check red K_5
    for five in itertools.combinations(range(n), 5):
        all_red = True
        for i, j in itertools.combinations(five, 2):
            if colors.get((i,j), colors.get((j,i))) == 1:
                all_red = False
                break
        if all_red:
            conflicts += 1
    # Check blue K_4
    for four in itertools.combinations(range(n), 4):
        all_blue = True
        for i, j in itertools.combinations(four, 2):
            if colors.get((i,j), colors.get((j,i))) == 0:
                all_blue = False
                break
        if all_blue:
            conflicts += 1
    return conflicts

def random_restart(n, max_iter=200000):
    # Initialize random coloring
    colors = {}
    for i in range(n):
        for j in range(i+1, n):
            colors[(i,j)] = random.randint(0, 1)

    best_colors = dict(colors)
    best_conflicts = count_conflicts_fast(colors, n)

    if best_conflicts == 0:
        return colors

    for iteration in range(max_iter):
        # Pick a random edge and flip it
        i = random.randint(0, n-1)
        j = random.randint(0, n-1)
        while j == i:
            j = random.randint(0, n-1)
        if i > j:
            i, j = j, i

        old_val = colors[(i,j)]
        colors[(i,j)] = 1 - old_val

        new_conflicts = count_conflicts_fast(colors, n)

        if new_conflicts < best_conflicts:
            best_conflicts = new_conflicts
            best_colors = dict(colors)
            if best_conflicts == 0:
                return colors

        # Simulated annealing acceptance
        temp = 1.0 * (0.01 / 1.0) ** (iteration / max_iter)
        if new_conflicts <= best_conflicts or random.random() < math.exp((best_conflicts - new_conflicts) / temp):
            pass
        else:
            colors[(i,j)] = old_val

        if iteration % 50000 == 0:
            print(f"Iteration {iteration}, best conflicts: {best_conflicts}")

    return None

