import itertools
import random
import math

n = 21

# Precompute all 5-sets and 4-sets
all_5sets = list(itertools.combinations(range(n), 5))
all_4sets = list(itertools.combinations(range(n), 4))

print(f"Number of 5-sets: {len(all_5sets)}")
print(f"Number of 4-sets: {len(all_4sets)}")

# For each edge, which 5-sets and 4-sets does it belong to?
edge_to_5sets = {}
edge_to_4sets = {}
for i in range(n):
    for j in range(i+1, n):
        edge_to_5sets[(i,j)] = []
        edge_to_4sets[(i,j)] = []

for idx, five in enumerate(all_5sets):
    for i, j in itertools.combinations(five, 2):
        edge_to_5sets[(i,j)].append(idx)

for idx, four in enumerate(all_4sets):
    for i, j in itertools.combinations(four, 2):
        edge_to_4sets[(i,j)].append(idx)

# Initialize random coloring
colors = {}
for i in range(n):
    for j in range(i+1, n):
        colors[(i,j)] = random.randint(0, 1)

# Track which 5-sets are all red and which 4-sets are all blue
red_5sets = set()
blue_4sets = set()

for idx, five in enumerate(all_5sets):
    all_red = True
    for i, j in itertools.combinations(five, 2):
        if colors[(i,j)] == 1:
            all_red = False
            break
    if all_red:
        red_5sets.add(idx)

for idx, four in enumerate(all_4sets):
    all_blue = True
    for i, j in itertools.combinations(four, 2):
        if colors[(i,j)] == 0:
            all_blue = False
            break
    if all_blue:
        blue_4sets.add(idx)

conflicts = len(red_5sets) + len(blue_4sets)
print(f"Initial conflicts: {conflicts}")

# Local search
best_conflicts = conflicts
best_colors = dict(colors)

for iteration in range(500000):
    # Pick a random edge
    i = random.randint(0, n-1)
    j = random.randint(0, n-1)
    while j == i:
        j = random.randint(0, n-1)
    if i > j:
        i, j = j, i

    old_val = colors[(i,j)]
    new_val = 1 - old_val

    # Compute delta conflicts
    delta = 0

    # For 5-sets containing this edge
    for five_idx in edge_to_5sets[(i,j)]:
        five = all_5sets[five_idx]
        if old_val == 0:  # was red, becoming blue
            if five_idx in red_5sets:
                delta -= 1  # this red K_5 is destroyed
        else:  # was blue, becoming red
            # Check if this creates a red K_5
            all_red = True
            for a, b in itertools.combinations(five, 2):
                if (a,b) == (i,j):
                    continue
                if colors[(a,b)] == 1:
                    all_red = False
                    break
            if all_red:
                delta += 1  # new red K_5 created

    # For 4-sets containing this edge
    for four_idx in edge_to_4sets[(i,j)]:
        four = all_4sets[four_idx]
        if old_val == 1:  # was blue, becoming red
            if four_idx in blue_4sets:
                delta -= 1  # this blue K_4 is destroyed
        else:  # was red, becoming blue
            # Check if this creates a blue K_4
            all_blue = True
            for a, b in itertools.combinations(four, 2):
                if (a,b) == (i,j):
                    continue
                if colors[(a,b)] == 0:
                    all_blue = False
                    break
            if all_blue:
                delta += 1  # new blue K_4 created

    new_conflicts = conflicts + delta

    # Accept if better or with some probability
    temp = 1.0 * (0.001 / 1.0) ** (iteration / 500000)
    if new_conflicts < conflicts or random.random() < math.exp((conflicts - new_conflicts) / temp):
        # Accept the flip
        colors[(i,j)] = new_val
        conflicts = new_conflicts

        # Update sets
        if old_val == 0:
            # Edge was red, now blue
            for five_idx in edge_to_5sets[(i,j)]:
                if five_idx in red_5sets:
                    red_5sets.remove(five_idx)
            # Check for new blue K_4
            for four_idx in edge_to_4sets[(i,j)]:
                four = all_4sets[four_idx]
                all_blue = True
                for a, b in itertools.combinations(four, 2):
                    if colors[(a,b)] == 0:
                        all_blue = False
                        break
                if all_blue:
                    blue_4sets.add(four_idx)
        else:
            # Edge was blue, now red
            for four_idx in edge_to_4sets[(i,j)]:
                if four_idx in blue_4sets:
                    blue_4sets.remove(four_idx)
            # Check for new red K_5
            for five_idx in edge_to_5sets[(i,j)]:
                five = all_5sets[five_idx]
                all_red = True
                for a, b in itertools.combinations(five, 2):
                    if colors[(a,b)] == 1:
                        all_red = False
                        break
                if all_red:
                    red_5sets.add(five_idx)

        if conflicts < best_conflicts:
            best_conflicts = conflicts
            best_colors = dict(colors)
            if best_conflicts == 0:
                print(f"Found solution at iteration {iteration}!")
                break

    if iteration % 50000 == 0:
        print(f"Iteration {iteration}, conflicts: {conflicts}, best: {best_conflicts}")

